create function family_private.group_rooms() returns jsonb language plpgsql stable security definer set search_path='' as $$begin if family_private.access_role() is null or not(select chat_enabled from public.family_settings where id) then raise exception 'الدردشة غير متاحة';end if;return coalesce((select jsonb_agg(to_jsonb(x)) from(select cg.id,cg.title,cg.kind,cg.owner_id,cg.starts_at,cg.ends_at,(cg.kind='group' or now() between cg.starts_at and cg.ends_at) as open_now from family_private.chat_groups cg join family_private.group_members m on m.group_id=cg.id where m.member_id=auth.uid() order by cg.created_at desc limit 100)x),'[]');end $$;
revoke all on function family_private.group_rooms() from public,anon;
grant execute on function family_private.group_rooms() to authenticated;
create or replace function public.group_action(action text,payload jsonb default '{}') returns jsonb language sql set search_path='' as $$select case when action='list' then family_private.group_rooms() else family_private.group_action(action,payload) end$$;
create or replace function family_private.profile_get() returns jsonb language plpgsql stable security definer set search_path='' as $$begin if auth.uid() is null then raise exception 'سجل الدخول';end if; return(select to_jsonb(d)||jsonb_build_object('display_name',p.display_name,'status',p.status,'role',p.role,'avatar_path',p.avatar_path,'endorsements_enabled',(select endorsements_enabled from public.family_settings where id)) from family_private.member_details d join public.profiles p on p.id=d.id where d.id=auth.uid());end $$;
